import pandas as pdimport numpy as npfrom sklearn.model_selection import StratifiedShuffleSplitfrom sklearn.pipeline import Pipelinefrom sklearn.compose import ColumnTransformerfrom sklearn.impute import SimpleImputerfrom sklearn.preprocessing import StandardScaler, OneHotEncoderhousing=pd.read_csv("dataset/housing.csv")print(housing)# 2. Create a stratified test set based on income categoryhousing["income_cat"] = pd.cut(    housing["median_income"],    bins=[0., 1.5, 3.0, 4.5, 6., np.inf],    labels=[1, 2, 3, 4, 5])split=StratifiedShuffleSplit(n_splits=1,test_size=0.2,random_state=42)for train_index, test_index in split.split(housing,housing['income_cat']):    start_train_set=housing.loc[train_index].drop("income_cat",axis=1)    start_test_set = housing.loc[test_index].drop("income_cat", axis=1)# we will work on the copy of training data.housing=start_train_set.copy()# separate feature and labels?housing_labels=housing["median_house_value"].copy()housing=housing.drop("median_house_value",axis=1)print(housing,housing_labels)